function resolveRoute(hash){const key=hash.replace(/^#/,"");return routeAliases[key]||(Object.prototype.hasOwnProperty.call(pages,key)?key:"home")}
function renderRoute(){
 const key=resolveRoute(location.hash),page=pages[key];
 document.getElementById('minigame-entrance').hidden=key!=='home';
 document.getElementById('simulation-search-open').hidden=key!=='home';
 document.querySelectorAll('[data-page]').forEach(panel=>{panel.hidden=panel.dataset.page!==key});
 const heading=document.getElementById('page-heading');heading.hidden=key==='home';
 document.getElementById('page-title').textContent=page.title;
 const gameTitle=key.endsWith('/esterification')?'esterification-title':key.endsWith('/alcohol-dehydration')?'alcohol-dehydration-title':key.endsWith('/carbonyl-addition')?'carbonyl-addition-title':key.endsWith('/methane-chlorination')?'methane-chlorination-title':key.endsWith('/anti-markovnikov')?'anti-markovnikov-title':key.endsWith('/acid-hydration')?'acid-hydration-title':key.endsWith('/bromination')?'bromination-title':key.endsWith('/e2')?'e2-title':key.endsWith('/e1')?'e1-title':key.endsWith('/markovnikov-hbr')?'hbr-title':key.endsWith('/sn2-hydroxide')?'sn2-title':key.endsWith('/sn1-hydroxide')?'sn1-title':null;
 document.getElementById('page-title').hidden=!!gameTitle;
 const back=document.getElementById('page-back');
 back.href='#'+(page.parent||'home');back.textContent='Back';back.hidden=key==='home';back.setAttribute('aria-label','Back to '+pages[page.parent||'home'].title);
 document.title=key==='home'?'Chemi':page.title+' · Chemi';
 window.scrollTo({top:0,behavior:'instant'});
 if(key!=='home')(document.getElementById('page-title').hidden?document.getElementById(gameTitle):document.getElementById('page-title')).focus({preventScroll:true});
}
window.addEventListener('hashchange',renderRoute);
renderRoute();
